"use client";
import { useState } from "react";
export function InvitationAcceptance({ id }: { id: string }) {
  const [message, setMessage] = useState("");
  const [pending, setPending] = useState(false);
  async function accept() {
    setPending(true);
    try {
      const response = await fetch("/api/invitations", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ operation: "accept", invitationId: id }) });
      if (!response.ok) { setMessage("Invitation unavailable. Confirm you signed in with the intended verified email and the invitation is still pending."); return; }
      window.location.assign("/");
    } catch { setMessage("Invitation processing is unavailable. Try again later."); }
    finally { setPending(false); }
  }
  return <div className="mt-6"><button disabled={pending} onClick={accept} className="rounded-sm border px-4 py-2">{pending ? "Accepting…" : "Accept invitation"}</button><p role="status">{message}</p></div>;
}

"use client";
import Link from"next/link";import{useRouter}from"next/navigation";import{useEffect,useRef,useState}from"react";import{ArrowRight,Plug,X}from"lucide-react";import{PROVIDER_CATALOG,type ConnectionExperience}from"@/lib/commerce/integration-experience";import{readCommerceActionResponse}from"@/lib/commerce/action-response";import{GovernedProviderActions}from"./governed-provider-actions";import{ShopifyWebhookRemediationHealth}from"./shopify-webhook-remediation-health";
import { connectionHealth } from "@/lib/commerce/connection-health";
type P="commas"|"everflow"|"shopify"|"next29"|"meta_ads"|"google_ads"|"tiktok_ads";
const status:Record<string,string>={connected:"text-emerald-300",degraded:"text-amber-200",missing:"text-rose-200",unavailable:"text-slate-300"};
function Status({value,label}:{value:string;label?:string}){return <span className={`rounded-full border border-white/10 bg-white/4 px-2.5 py-1 text-[10px] font-semibold uppercase tracking-wider ${status[value]||status.unavailable}`}>{label||value.replaceAll("_"," ")}</span>}
export function ConnectionsOverview({connections,organizationName,callbackNotice,googleSelectionConnectionId}:{connections:ConnectionExperience[];organizationName?:string|null;callbackNotice?:{tone:"success"|"info"|"error";text:string}|null;googleSelectionConnectionId?:string|null}){const[p,setP]=useState<P|null>(null),connected=connections.filter(c=>c.status==="connected").length,healthy=connections.filter(c=>connectionHealth(c).state==="healthy").length,last=connections.map(c=>c.lastVerifiedAt).filter((v):v is string=>!!v).sort().at(-1);return <div className="min-h-full bg-[#080a0f] text-slate-100"><div className="mx-auto max-w-[1360px] px-5 py-8 sm:px-8 lg:px-10"><header className="flex flex-col gap-6 border-b border-white/10 pb-8 lg:flex-row lg:items-end lg:justify-between"><div><div className="tk-brand-eyebrow text-[10px] font-semibold uppercase tracking-[.2em]">Client data connections</div><h1 className="mt-3 text-3xl font-semibold sm:text-4xl">Connections{organizationName?` for ${organizationName}`:""}</h1><p className="mt-3 max-w-2xl text-sm text-slate-400">Connect the commerce and performance systems that supply this Client Organization&apos;s TraceKit evidence, attribution, and financial reconciliation.</p></div><nav className="flex gap-2 text-xs"><Link href="/connections/commerce" className="tk-workspace-tab-active rounded-lg px-3 py-2">Connections</Link><Link href="/connections/sync-runs" className="tk-workspace-tab-inactive rounded-lg px-3 py-2">Sync Runs</Link><Link href="/connections/readiness" className="tk-workspace-tab-inactive rounded-lg px-3 py-2">Readiness</Link></nav></header>{callbackNotice?<div role="status" className={`mt-5 rounded-xl border px-4 py-3 text-sm ${callbackNotice.tone==="success"?"border-emerald-400/20 bg-emerald-400/10 text-emerald-100":callbackNotice.tone==="error"?"border-rose-400/20 bg-rose-400/10 text-rose-100":"border-blue-400/20 bg-blue-400/10 text-blue-100"}`}>{callbackNotice.text}</div>:null}<section className="mt-8 grid gap-3 sm:grid-cols-3"><Card label="Connected" value={String(connected)} detail={`${healthy} with successful sync history`}/><Card label="Providers" value={String(PROVIDER_CATALOG.length)} detail="Commerce + performance marketing"/><Card label="Last verification" value={last?fmt(last):"Not available"} detail="Stored server state"/></section><section className="mt-8"><div className="flex flex-wrap items-end justify-between gap-3"><div><h2 className="text-lg font-semibold">Connected systems</h2><p className="mt-1 text-xs text-slate-500">Credentials, account identity, capabilities, sync state, and operational health remain scoped to the active Client Organization.</p></div>{organizationName?<span className="rounded-full border border-blue-400/20 bg-blue-400/10 px-3 py-1.5 text-[10px] font-semibold uppercase tracking-[.12em] text-blue-100">Active client · {organizationName}</span>:null}</div><div className="mt-4 grid gap-4 md:grid-cols-2 xl:grid-cols-3">{PROVIDER_CATALOG.map(provider=>{const rows=connections.filter(c=>c.provider===provider.provider),c=rows[0],can=["commas","everflow","shopify","next29","meta_ads","google_ads","tiktok_ads"].includes(provider.provider);return <article key={provider.provider} className="flex min-h-64 flex-col rounded-2xl border border-white/10 bg-white/[.035] p-5"><div className="flex items-start justify-between"><div className="flex h-11 w-11 items-center justify-center rounded-xl border border-white/10 bg-white/6"><Plug className="h-5 w-5"/></div>{c?<Status value={c.status}/>:<Status value="unavailable" label={provider.availability==="available"?"Not Connected":"Coming Soon"}/>}</div><h3 className="mt-5 text-lg font-semibold">{provider.name}</h3>{c?<><p className="mt-1 text-xs text-slate-400">{c.displayName} · {c.organizationName}</p><p className={connectionHealth(c).state==="degraded"?"mt-2 text-xs text-amber-200":"mt-2 text-xs text-slate-400"}>{connectionHealth(c).state==="degraded"?"Needs attention · ":connectionHealth(c).state==="unknown"?"Health unverified · ":""}{connectionHealth(c).detail}</p>{c.providerAccountLabel?<p className="mt-1 text-[11px] text-slate-500">Account / Store · {c.providerAccountLabel}</p>:null}{rows.length>1?<p className="mt-1 text-[11px] text-cyan-300">{rows.length} {provider.name} connections</p>:null}<div className="mt-auto flex gap-4 pt-5"><Link href={`/connections/${["meta_ads","google_ads","tiktok_ads"].includes(c.provider)?"marketing":"commerce"}/${c.id}`} className="tk-brand-link inline-flex items-center gap-2 text-xs font-semibold">View Connection <ArrowRight className="h-3.5 w-3.5"/></Link>{provider.provider==="everflow"?<Add onClick={()=>setP("everflow")}>Add Network</Add>:null}{provider.provider==="shopify"?<Add onClick={()=>setP("shopify")}>Add Store</Add>:null}{provider.provider==="next29"?<Add onClick={()=>setP("next29")}>Add Store</Add>:null}</div></>:<><p className="mt-2 text-xs leading-5 text-slate-500">{provider.availability==="available"?"Securely connect a provider account to begin verification.":"Provider adapter planned; no connection is active."}</p>{can?<button onClick={()=>setP(provider.provider as P)} className="mt-auto inline-flex items-center gap-2 pt-5 text-left text-xs font-semibold text-blue-300 hover:text-blue-200">Connect {provider.name}<ArrowRight className="h-3.5 w-3.5"/></button>:<span className="mt-auto pt-5 text-[10px] uppercase tracking-widest text-slate-600">Not available</span>}</>}</article>})}</div></section><ShopifyWebhookRemediationHealth/><GovernedProviderActions/></div>{p?<ConnectDialog provider={p} close={()=>setP(null)}/>:null}{googleSelectionConnectionId?<GoogleAccountPicker connectionId={googleSelectionConnectionId}/>:null}</div>}
function ConnectDialog({provider,close}:{provider:P;close:()=>void}){const router=useRouter(),[busy,setBusy]=useState(false),[message,setMessage]=useState<string|null>(null),key=useRef<string|null>(null),ef=provider==="everflow",shop=provider==="shopify",n29=provider==="next29",oauth=provider==="meta_ads"||provider==="google_ads"||provider==="tiktok_ads",name=provider==="meta_ads"?"Meta Ads":provider==="google_ads"?"Google Ads":provider==="tiktok_ads"?"TikTok Ads":ef?"Everflow":shop?"Shopify":n29?"29Next":"Commas";async function submit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();if(busy)return;setBusy(true);setMessage(null);const target=e.currentTarget,f=new FormData(target);try{if(oauth){const path=provider==="meta_ads"?"/v1/integrations/meta/oauth/start":provider==="google_ads"?"/v1/integrations/google-ads/oauth/start":"/v1/integrations/tiktok/oauth/start";location.assign(path);return}if(shop){const q=new URLSearchParams({shop:String(f.get("shopDomain")||"").trim(),displayName:String(f.get("displayName")||"Shopify Store").trim()});location.assign(`/api/shopify/oauth/start?${q}`);return}key.current||=crypto.randomUUID();let response:Response;if(ef)response=await fetch("/v1/integrations/everflow/connect",{method:"POST",headers:{"Content-Type":"application/json","Idempotency-Key":key.current},body:JSON.stringify({displayName:f.get("displayName"),apiKey:f.get("apiKey"),networkId:f.get("networkId")})});else if(n29)response=await fetch("/api/next29/connect",{method:"POST",headers:{"Content-Type":"application/json","Idempotency-Key":key.current},body:JSON.stringify({displayName:f.get("displayName"),store:f.get("store"),accessToken:f.get("accessToken")})});else{response=await fetch("/api/commerce/connections",{method:"POST",headers:{"Content-Type":"application/json","Idempotency-Key":key.current},body:JSON.stringify({provider:"commas",displayName:f.get("displayName"),environment:f.get("environment"),apiKey:f.get("apiKey")})});const r=await readCommerceActionResponse(response);if(!r.ok||!r.connectionId){setMessage(r.ok?"TraceKit returned an incomplete response.":r.message);return}target.reset();key.current=null;router.push(`/connections/commerce/${r.connectionId}`);router.refresh();return}const r=await response.json().catch(()=>null)as{ok?:boolean;message?:string;connectionId?:string}|null;if(!response.ok||!r?.ok||!r.connectionId){setMessage(r?.message||`TraceKit could not verify the ${name} connection.`);return}target.reset();key.current=null;router.push(`/connections/commerce/${r.connectionId}`);router.refresh()}catch{setMessage(`TraceKit could not reach the ${name} connection service. Please try again.`)}finally{setBusy(false)}}return <Dialog title={`Connect ${name}`} close={close}><form onSubmit={submit} className="space-y-4">{oauth?<p className="text-xs leading-5 text-slate-400">Continue to {name} to authorize TraceKit. Credentials are handled by the provider OAuth flow; production data ingestion certification is tracked separately.</p>:<Field label="Display name"><input required name="displayName" className="input" autoComplete="off" placeholder={n29?"StemLabs v3":shop?"Main Shopify Store":ef?"Accufy Everflow":"Push Button Systems"}/></Field>}{!oauth&&!ef&&!shop&&!n29?<Field label="Environment"><select name="environment" className="input"><option value="production">Production</option><option value="sandbox">Sandbox</option></select></Field>:null}{ef?<Field label="Network ID (optional)"><input name="networkId" className="input" inputMode="numeric" placeholder="Leave blank to discover from Everflow"/></Field>:null}{shop?<Field label="Shop domain"><input required name="shopDomain" className="input" placeholder="your-store.myshopify.com"/></Field>:null}{n29?<><Field label="Store"><input required name="store" className="input" placeholder="stemlabs or stemlabs.29next.store"/></Field><Field label="29Next Admin API access token"><input required minLength={8} name="accessToken" type="password" autoComplete="new-password" className="input" placeholder="Stored encrypted; never shown again"/></Field></>:null}{!oauth&&!shop&&!n29?<Field label="API key"><input required minLength={8} name="apiKey" type="password" autoComplete="new-password" className="input" placeholder="Stored encrypted; never shown again"/></Field>:null}<p className="text-[11px] leading-5 text-slate-500">Client Organization scope is derived from your authenticated TraceKit session. {oauth?"Authorization does not enable or certify ingestion.":n29?"The 29Next Admin API token is encrypted at rest and never returned to the browser.":shop?"You will be redirected to Shopify to authorize TraceKit.":"The API key is sent only to the authorized server operation."}</p>{message?<p role="alert" className="rounded-xl border border-rose-400/20 bg-rose-400/5 px-3 py-2 text-xs text-rose-300">{message}</p>:null}<button disabled={busy} className="w-full rounded-xl bg-white px-4 py-2.5 text-sm font-semibold text-slate-950 disabled:opacity-50">{busy?"Connecting…":oauth?`Continue to ${name}`:shop?"Continue to Shopify":"Create Connection"}</button></form></Dialog>}
function Card({label,value,detail}:{label:string;value:string;detail:string}){return <div className="rounded-xl border border-white/10 bg-white/2.5 p-4"><p className="tk-label">{label}</p><p className="mt-2 text-xl font-semibold">{value}</p><p className="mt-1 text-[11px] text-slate-500">{detail}</p></div>}
function Add({onClick,children}:{onClick:()=>void;children:React.ReactNode}){return <button type="button" onClick={onClick} className="rounded-lg border border-white/15 bg-white/6 px-3 py-1.5 text-xs font-semibold text-slate-100 hover:border-blue-400/30 hover:bg-blue-400/10 hover:text-blue-100">{children}</button>}
function Dialog({title,close,children}:{title:string;close:()=>void;children:React.ReactNode}){return <div role="dialog" aria-modal="true" className="fixed inset-0 z-50 flex items-center justify-center bg-black/75 p-4"><div className="w-full max-w-md rounded-2xl border border-white/15 bg-[#10131a] p-6"><div className="mb-5 flex items-center justify-between"><h2 className="text-lg font-semibold">{title}</h2><button onClick={close} aria-label="Close" className="p-2 text-slate-400"><X className="h-4 w-4"/></button></div>{children}</div></div>}
function Field({label,children}:{label:string;children:React.ReactNode}){return <label className="block text-xs font-medium text-slate-300"><span className="mb-2 block">{label}</span>{children}</label>}
function fmt(v:string){return new Intl.DateTimeFormat("en",{dateStyle:"medium",timeStyle:"short"}).format(new Date(v))}

function GoogleAccountPicker({connectionId}:{connectionId:string}){const router=useRouter(),[accounts,setAccounts]=useState<Array<{id:string;label:string|null;externalId:string;selectedForSync:boolean}>>([]),[selected,setSelected]=useState<string[]>([]),[busy,setBusy]=useState(false),[message,setMessage]=useState<string|null>(null);useEffect(()=>{let live=true;fetch(`/v1/integrations/google-ads/accounts?connectionId=${encodeURIComponent(connectionId)}`,{cache:"no-store"}).then(r=>r.json()).then((r:{ok?:boolean;accounts?:Array<{id:string;label:string|null;externalId:string;selectedForSync:boolean}>})=>{if(!live||!r.ok)return;const rows=r.accounts||[];setAccounts(rows);setSelected(rows.filter(a=>a.selectedForSync).map(a=>a.id))}).catch(()=>{if(live)setMessage("TraceKit could not load Google Ads accounts.")});return()=>{live=false}},[connectionId]);async function save(){if(!selected.length){setMessage("Select at least one Google Ads account.");return}setBusy(true);setMessage(null);try{const response=await fetch("/v1/integrations/google-ads/accounts",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({connectionId,accountIds:selected})});const r=await response.json().catch(()=>null)as{ok?:boolean;message?:string}|null;if(!response.ok||!r?.ok){setMessage(r?.message||"TraceKit could not save the Google Ads account selection.");return}router.replace("/connections?provider=google_ads&google=connected");router.refresh()}catch{setMessage("TraceKit could not save the Google Ads account selection.")}finally{setBusy(false)}}return <Dialog title="Choose Google Ads accounts" close={()=>router.replace("/connections")}><div className="space-y-4"><p className="text-xs leading-5 text-slate-400">Select the advertiser account(s) TraceKit should use. Discovered accounts remain unselected until you confirm.</p><div className="max-h-72 space-y-2 overflow-y-auto">{accounts.map(a=><label key={a.id} className="flex cursor-pointer items-center gap-3 rounded-xl border border-white/10 bg-white/[.035] px-3 py-3"><input type="checkbox" checked={selected.includes(a.id)} onChange={e=>setSelected(v=>e.target.checked?[...v,a.id]:v.filter(id=>id!==a.id))}/><span><span className="block text-sm font-medium text-slate-100">{a.label||"Google Ads account"}</span><span className="block text-[11px] text-slate-500">Customer · {a.externalId}</span></span></label>)}</div>{!accounts.length&&!message?<p className="text-xs text-slate-500">Loading accounts…</p>:null}{message?<p role="alert" className="rounded-xl border border-rose-400/20 bg-rose-400/5 px-3 py-2 text-xs text-rose-300">{message}</p>:null}<button type="button" disabled={busy||!accounts.length} onClick={save} className="w-full rounded-xl bg-white px-4 py-2.5 text-sm font-semibold text-slate-950 disabled:opacity-50">{busy?"Saving…":"Connect selected accounts"}</button></div></Dialog>}

"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useEffect, useState } from "react";
import type { ConnectionExperience } from "@/lib/commerce/integration-experience";

export function EverflowNetworkSelector({ connections, selectedId }: { connections: ConnectionExperience[]; selectedId?: string }) {
  const everflow = connections.filter((connection) => connection.provider === "everflow");
  if (!everflow.length) return null;
  return <section className="mt-6 rounded-2xl border border-white/10 bg-white/[.035] p-5"><div className="flex flex-wrap items-end justify-between gap-4"><div><p className="tk-label">Everflow networks</p><h2 className="mt-2 text-sm font-semibold">{everflow.length} connected instance{everflow.length === 1 ? "" : "s"}</h2><p className="mt-2 text-xs text-slate-500">Select a network to view and operate only that connection.</p></div><div className="flex flex-wrap gap-2">{everflow.map((connection) => <Link key={connection.id} href={`/connections/commerce/${connection.id}`} className={`rounded-lg border px-3 py-2 text-xs font-semibold ${connection.id === selectedId ? "border-cyan/40 bg-cyan/10 text-cyan-100" : "border-white/10 bg-white/3 text-slate-300 hover:border-white/20"}`}>{connection.displayName}{connection.providerAccountLabel ? ` · NID ${connection.providerAccountLabel}` : ""}</Link>)}</div></div></section>;
}

export function EverflowManualSync({ connection }: { connection: ConnectionExperience }) {
  const [busy, setBusy] = useState(false); const [notice, setNotice] = useState<string | null>(null); const router = useRouter();
  if (connection.provider !== "everflow" || !connection.canManage) return null;
  const label = `${connection.displayName}${connection.providerAccountLabel ? ` · NID ${connection.providerAccountLabel}` : ""}`;
  async function run() { setBusy(true); setNotice(null); try { const response = await fetch(`/api/commerce/connections/${connection.id}/sync-now`, { method: "POST", headers: { "content-type": "application/json" }, body: "{}" }); const result = await response.json().catch(() => ({})) as { message?: string; code?: string }; if (!response.ok) throw new Error(result.message || result.code || "Manual Everflow sync was not started."); setNotice(`Sync started for ${label}. Refreshing run state…`); router.refresh(); window.setTimeout(() => router.refresh(), 2500); } catch (error) { setNotice(error instanceof Error ? error.message : "Manual Everflow sync was not started."); } finally { setBusy(false); } }
  return <section className="mt-4 rounded-2xl border border-cyan-400/30 bg-[#0b111a] p-5 shadow-lg shadow-black/20"><div className="flex flex-wrap items-center justify-between gap-5"><div><p className="text-[10px] font-semibold uppercase tracking-[.18em] text-cyan-300">Manual synchronization</p><h2 className="mt-2 text-base font-semibold text-white">{label}</h2><p className="mt-2 text-xs leading-5 text-slate-400">Runs only this selected Everflow connection through the guarded server sync path.</p></div><button type="button" onClick={run} disabled={busy} className="min-w-32 rounded-lg border border-cyan-300/50 bg-cyan-300 px-5 py-2.5 text-sm font-bold text-slate-950 shadow-md transition hover:bg-cyan-200 disabled:cursor-not-allowed disabled:opacity-50">{busy ? "Starting…" : "Run Sync"}</button></div>{notice ? <p role="status" className="mt-4 rounded-lg border border-white/10 bg-white/4 px-3 py-2 text-xs text-slate-300">{notice}</p> : null}</section>;
}


export function EverflowHistoricalImport({ connection }: { connection: ConnectionExperience }) {
  const [busy,setBusy]=useState(false),[notice,setNotice]=useState<string|null>(null),[startDate,setStartDate]=useState(""),[endDate,setEndDate]=useState(""),[runState,setRunState]=useState<any>(null); const router=useRouter();
  async function refreshStatus(){try{const response=await fetch(`/api/commerce/connections/${connection.id}/historical-import`,{cache:"no-store"});const result=await response.json().catch(()=>({}));if(response.ok){setRunState(result.run||null);const persisted=String(result.run?.effective_status||result.run?.status||"");if(persisted&&persisted!=="queued")setNotice(null);}}catch{}}
  useEffect(()=>{if(connection.provider!=="everflow"||!connection.canManage)return;void refreshStatus();const timer=window.setInterval(()=>void refreshStatus(),5000);return()=>window.clearInterval(timer)},[connection.id,connection.provider,connection.canManage]);
  if(connection.provider!=="everflow"||!connection.canManage)return null;
  async function run(){if(!startDate||!endDate||busy)return;setBusy(true);setNotice(null);try{const response=await fetch(`/api/commerce/connections/${connection.id}/historical-import`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({startDate,endDate})});const result=await response.json().catch(()=>({})) as {message?:string;code?:string;runId?:string};if(!response.ok)throw new Error(result.message||result.code||"Historical Everflow import could not be queued.");setNotice(result.message||"Historical import queued.");await refreshStatus();router.refresh();}catch(error){setNotice(error instanceof Error?error.message:"Historical Everflow import could not be queued.");}finally{setBusy(false)}}
  const state=String(runState?.effective_status||runState?.status||""),running=state==="queued"||state==="running",interrupted=state==="interrupted",failed=state==="failed",completed=state==="completed"||state==="completed_with_warnings",meta=runState?.metadata||{},rangeLabel=meta.from&&meta.to?`${String(meta.from).slice(0,10)} → ${String(meta.to).slice(0,10)}`:null;
  return <section className="mt-4 rounded-2xl border border-white/10 bg-[#0b111a] p-5"><div className="flex flex-wrap items-start justify-between gap-5"><div><p className="text-[10px] font-semibold uppercase tracking-[.18em] text-cyan-300">Historical import</p><h2 className="mt-2 text-base font-semibold text-white">Import a bounded Everflow date range</h2><p className="mt-2 max-w-2xl text-xs leading-5 text-slate-400">Adds historical conversion evidence for this selected network without moving the normal incremental sync cursor. Imported conversions are persisted and run through TraceKit&apos;s existing order-linkage pipeline.</p></div><div className="grid w-full gap-3 sm:w-auto sm:grid-cols-[150px_150px_auto]"><label className="text-[11px] text-slate-400"><span className="mb-1 block">Start date</span><input type="date" value={startDate} onChange={e=>setStartDate(e.target.value)} className="w-full rounded-lg border border-white/10 bg-white/4 px-3 py-2 text-sm text-white"/></label><label className="text-[11px] text-slate-400"><span className="mb-1 block">End date</span><input type="date" value={endDate} onChange={e=>setEndDate(e.target.value)} className="w-full rounded-lg border border-white/10 bg-white/4 px-3 py-2 text-sm text-white"/></label><button type="button" onClick={run} disabled={busy||running||!startDate||!endDate} className="self-end rounded-lg border border-cyan-300/50 bg-cyan-300 px-5 py-2.5 text-sm font-bold text-slate-950 hover:bg-cyan-200 disabled:cursor-not-allowed disabled:opacity-50">{busy?"Queuing…":running?"Import Running":"Run Historical Import"}</button></div></div><div className="mt-3 text-[11px] text-slate-500">Conversions · Maximum 31 calendar days per run · Existing live cursor is preserved</div>
